'use client';
import { useId, type ReactNode } from 'react';
import PollResultBars from '../../../effects/poll-result-bars';
import { meta as pollMeta } from '../../../effects/poll-result-bars/meta';
import type { EffectMeta, ParamValues } from '../../../types';
import { CLOSES } from './data';
import { MultiPoll } from './MultiPoll';
import { Quiz } from './Quiz';
import { Ranking } from './Ranking';
import styles from './styles.module.css';

const defaults = (m: EffectMeta): ParamValues => Object.fromEntries(m.params.map((p) => [p.key, p.default]));
const MHZ = [88, 90, 92, 94, 96, 98, 100, 102, 104, 106, 108];
const x = (f: number) => 8 + ((f - 87.5) / (108 - 87.5)) * 384;

/** The FM band with the station's needle at 98.2 MHz. */
function Dial() {
  return (
    <svg viewBox="0 0 400 64" className={styles.dial} aria-hidden="true" focusable="false">
      <path d="M8 40H392" className={styles.dialLine} />
      {Array.from({ length: 103 }, (_, i) => 87.6 + i * 0.2).map((f) => (
        <path key={f.toFixed(1)} d={`M${x(f).toFixed(1)} 40v${Math.abs(f - Math.round(f)) < 0.05 ? -10 : -5}`} className={styles.dialTick} />
      ))}
      {MHZ.map((f) => <text key={f} x={x(f)} y="58" textAnchor="middle" className={styles.dialNum}>{f}</text>)}
      <path d={`M${x(98.2)} 4V48`} className={styles.needle} />
      <circle cx={x(98.2)} cy="4" r="3.5" className={styles.needleCap} />
    </svg>
  );
}

function Card({ id, slug, title, note, children, wide }: { id: string; slug: string; title: string; note: string; children: ReactNode; wide?: boolean }) {
  return (
    <section className={styles.cue} data-wide={wide || undefined} aria-labelledby={id}>
      <p className={styles.slug}>{slug}</p>
      <h3 id={id} className={styles.cueTitle}>{title}</h3>
      <p className={styles.small}>{note}</p>
      {children}
    </section>
  );
}

export default function InteractivePoll() {
  const uid = useId();
  return (
    <div className={styles.root}>
      <header className={styles.masthead}>
        <div className={styles.mastRow}>
          <p className={styles.onAir}>On air</p>
          <p className={styles.sample}><span className="mk-label">Sample content</span> Quay FM, its shows and every count are fictional.</p>
        </div>
        <h2 className={styles.station}>Quay FM <span className={styles.freq}>98.2</span></h2>
        <p className={styles.tagline}>Community radio for the harbour. This week’s listener polls — results appear after you vote, and everything closes {CLOSES.text}.</p>
        <Dial />
      </header>

      <div className={styles.grid}>
        <Card id={`${uid}-p1`} slug="Poll 01 · single choice · Sunday book hour" title="Help pick Sunday’s reading spot" note="One answer. You can change it while the poll is open.">
          <div className={styles.composed}>
            <PollResultBars params={{ ...defaults(pollMeta), duration: 1000, stagger: 90, easing: 'emphasized', highlight: 'choice', countUp: true }} />
          </div>
        </Card>

        <Card id={`${uid}-p2`} slug="Poll 02 · multiple choice · morning listening" title="When are you with us?" note="Shaping next season’s schedule. Tick every slot you listen to.">
          <MultiPoll />
        </Card>

        <Card id={`${uid}-p3`} slug="Quiz · three questions · no timer" title="Were you listening this week?" note="Each answer comes with the explanation from the show.">
          <Quiz />
        </Card>

        <Card id={`${uid}-p4`} slug="Poll 03 · ranking · tomorrow 07:00" title="Order tomorrow’s Early Edit" note="Drag the handles — or focus one, press Space, use ↑ ↓, Space to drop — then send your order. The producer reads the listeners’ order on air." wide>
          <Ranking />
        </Card>
      </div>

      <footer className={styles.footer}>
        <p>Quay FM 98.2, The Early Edit and every vote, ballot and listener count on this page are sample content. Live votes are simulated in your browser and labelled where they appear. Nothing you choose is sent anywhere.</p>
      </footer>
    </div>
  );
}

/**
 * Sample content for Quay FM's listener polls. The station, its shows and every count are fictional; the
 * "live" votes are generated in the browser from a seeded random sequence and are labelled as simulated.
 */
export const CLOSES = { iso: '2026-11-27T18:00:00Z', text: 'Friday 27 November, 18:00 GMT' };

export const SLOTS = [
  { id: 'early', label: '6–7 · The early hour' },
  { id: 'edit', label: '7–8 · The Early Edit' },
  { id: 'talk', label: '8–9 · Harbour talk' },
  { id: 'music', label: '9–10 · Music till ten' },
] as const;
export type SlotId = (typeof SLOTS)[number]['id'];
/** Sample: how many of the 640 respondents ticked each slot (more than one allowed). */
export const SLOT_BASE: Record<SlotId, number> = { early: 212, edit: 498, talk: 301, music: 263 };
export const SLOT_RESPONDENTS = 640;
/** Chance that a simulated listener ticks each slot. */
export const SLOT_ODDS: Record<SlotId, number> = { early: 0.32, edit: 0.78, talk: 0.46, music: 0.41 };

export interface QuizQuestion { q: string; options: readonly string[]; answer: number; explain: string }
export const QUIZ: readonly QuizQuestion[] = [
  {
    q: 'How many high tides does most of the coast get in a day?',
    options: ['One', 'Two', 'Four'],
    answer: 1,
    explain: 'Two, roughly 12 hours 25 minutes apart: the Moon raises a bulge of water on both sides of the Earth.',
  },
  {
    q: 'What does a harbour pilot do?',
    options: ['Flies the coastguard helicopter', 'Guides visiting ships through local waters', 'Runs the ferry ticket office'],
    answer: 1,
    explain: 'Pilots board incoming ships and steer them through the channel, because they know the local sandbanks and currents.',
  },
  {
    q: 'On the radio, what is a “cold open”?',
    options: ['Starting straight into the content, before any theme music', 'A segment recorded outdoors in winter', 'The first weather report of the day'],
    answer: 0,
    explain: 'A cold open drops you straight into the programme; the theme and introductions come after it.',
  },
];

/** Running-order titles exactly as the drag-reorder-list recipe renders them (its ballot is read from the page). */
export const RUNNING = [
  { id: 'open', title: 'Cold open', avg: 1.6 },
  { id: 'news', title: 'Headlines', avg: 2.3 },
  { id: 'roads', title: 'Weather and roads', avg: 2.8 },
  { id: 'pilot', title: 'Interview: a harbour pilot', avg: 4.1 },
  { id: 'letters', title: 'Listener letters', avg: 4.7 },
  { id: 'music', title: 'Music break', avg: 5.3 },
  { id: 'close', title: 'Sign-off', avg: 6.8 },
] as const;
export const RUNNING_BALLOTS = 312;

'use client';
/**
 * Multiple-choice poll. Results stay hidden until you vote (the promise is stated up front), then show as
 * meter bars on one shared scale. Percentages are "of respondents", so they do not add up to 100 — said in words.
 * After voting, simulated live votes arrive about every 1.4 s: clearly labelled, pausable, finite (40 votes),
 * and paused from the start under reduced motion.
 */
import { useEffect, useId, useRef, useState, type FormEvent } from 'react';
import { useStudioMotion } from '../../../motion';
import { CLOSES, SLOTS, SLOT_BASE, SLOT_ODDS, SLOT_RESPONDENTS, type SlotId } from './data';
import styles from './styles.module.css';

const LIVE_MS = 1400;
const LIVE_CAP = 40;
const LEDS = 24;

function rng(seed: number) {
  let a = seed >>> 0;
  return () => { a = (a + 0x6d2b79f5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}

export function MultiPoll() {
  const { reduced } = useStudioMotion();
  const uid = useId();
  const [picks, setPicks] = useState<Set<SlotId>>(new Set());
  const [voted, setVoted] = useState<Set<SlotId> | null>(null);
  const [counts, setCounts] = useState<Record<SlotId, number>>({ ...SLOT_BASE });
  const [people, setPeople] = useState(SLOT_RESPONDENTS);
  const [added, setAdded] = useState(0);
  const [live, setLive] = useState<'running' | 'paused' | 'done'>('paused');
  const [hint, setHint] = useState('');
  const [say, setSay] = useState('');
  const random = useRef(rng(97));
  const addedRef = useRef(0);
  const resultsHead = useRef<HTMLHeadingElement>(null);
  const firstBox = useRef<HTMLInputElement>(null);
  const focusTo = useRef<'results' | 'form' | null>(null);

  useEffect(() => {
    const to = focusTo.current;
    focusTo.current = null;
    if (to === 'results') resultsHead.current?.focus();
    if (to === 'form') firstBox.current?.focus();
  }, [voted]);

  useEffect(() => {
    if (live !== 'running') return;
    const t = setInterval(() => {
      const r = random.current;
      const ticked = SLOTS.filter((s) => r() < SLOT_ODDS[s.id]).map((s) => s.id);
      const pick = ticked.length ? ticked : [SLOTS[1].id];
      setCounts((c) => { const n = { ...c }; for (const id of pick) n[id] += 1; return n; });
      setPeople((p) => p + 1);
      addedRef.current += 1;
      setAdded(addedRef.current);
      if (addedRef.current >= LIVE_CAP) setLive('done');
    }, LIVE_MS);
    return () => clearInterval(t);
  }, [live]);

  const toggle = (id: SlotId) => setPicks((p) => { const n = new Set(p); if (n.has(id)) n.delete(id); else n.add(id); return n; });
  const submit = (e: FormEvent) => {
    e.preventDefault();
    if (!picks.size) { setHint('Tick at least one slot, then vote.'); return; }
    setHint('');
    const next = { ...counts };
    for (const id of picks) next[id] += 1;
    const total = people + 1;
    setCounts(next);
    setPeople(total);
    setVoted(new Set(picks));
    setLive(added >= LIVE_CAP ? 'done' : reduced ? 'paused' : 'running');
    setSay(`Vote counted. ${SLOTS.map((s) => `${s.label}: ${Math.round((next[s.id] / total) * 100)}%${picks.has(s.id) ? ', your pick' : ''}`).join('. ')}.`);
    focusTo.current = 'results';
  };
  const change = () => {
    if (!voted) return;
    setCounts((c) => { const n = { ...c }; for (const id of voted) n[id] -= 1; return n; });
    setPeople((p) => p - 1);
    setLive((l) => (l === 'done' ? l : 'paused'));
    setVoted(null);
    setSay('');
    focusTo.current = 'form';
  };

  const max = Math.max(...SLOTS.map((s) => counts[s.id] / people));
  return (
    <div className={styles.poll}>
      {voted ? (
        <div>
          <h4 ref={resultsHead} tabIndex={-1} className={styles.question}>Which parts of the morning do you listen to?</h4>
          <ul className={styles.meters}>
            {SLOTS.map((s) => {
              const share = counts[s.id] / people;
              const lit = Math.round((share / Math.max(max, 0.0001)) * LEDS * 0.92);
              return (
                <li key={s.id} className={styles.meterRow}>
                  <span className={styles.meterLabel}>
                    {s.label}
                    {voted.has(s.id) ? <span className={styles.tag}>Your pick</span> : null}
                  </span>
                  <span className={styles.meterValue}>{Math.round(share * 100)}% <span className={styles.muted}>({counts[s.id].toLocaleString('en-GB')})</span></span>
                  <span className={styles.meter} aria-hidden="true">
                    {Array.from({ length: LEDS }, (_, i) => <i key={i} data-on={i < lit || undefined} data-peak={(i < lit && i >= LEDS - 3) || undefined} />)}
                  </span>
                </li>
              );
            })}
          </ul>
          <p className={styles.small}>
            {people.toLocaleString('en-GB')} listeners answered (sample data). You could pick more than one slot, so the percentages don’t add up to 100.
          </p>
          <div className={styles.liveRow}>
            <p className={styles.liveText}>
              <span className={styles.liveDot} data-on={live === 'running' || undefined} aria-hidden="true" />
              Simulated live votes, generated in your browser — not real listeners: +{added}
              {live === 'done' ? ' · simulation finished' : live === 'paused' ? ' · paused' : ''}
            </p>
            {live === 'done' ? null : (
              <button type="button" className={styles.ghost} aria-pressed={live === 'paused'} onClick={() => setLive((l) => (l === 'running' ? 'paused' : 'running'))}>
                {live === 'running' ? 'Pause live votes' : 'Resume live votes'}
              </button>
            )}
          </div>
          <button type="button" className={styles.ghost} onClick={change}>Change my answer</button>
        </div>
      ) : (
        <form onSubmit={submit} noValidate>
          <fieldset className={styles.fieldset} aria-describedby={`${uid}-rules`}>
            <legend className={styles.question}>Which parts of the morning do you listen to?</legend>
            <p id={`${uid}-rules`} className={styles.small}>Pick as many as you like. Results appear after you vote; the poll closes {CLOSES.text}.</p>
            <div className={styles.options}>
              {SLOTS.map((s, i) => (
                <label key={s.id} className={styles.option}>
                  <input ref={i === 0 ? firstBox : undefined} type="checkbox" checked={picks.has(s.id)} onChange={() => { toggle(s.id); setHint(''); }} />
                  <span>{s.label}</span>
                </label>
              ))}
            </div>
          </fieldset>
          <div className={styles.actions}>
            <button type="submit" className={styles.primary}>Vote</button>
            <p className={styles.small} role="status">{hint || `${SLOT_RESPONDENTS.toLocaleString('en-GB')} listeners so far · sample data`}</p>
          </div>
        </form>
      )}
      <p className="mk-sr-only" role="status">{say}</p>
    </div>
  );
}

'use client';
/**
 * Quiz variant: one question at a time, no timer. "Check answer" turns into "Next question" on the same button,
 * so keyboard focus never jumps; feedback is words plus a mark (never colour alone) and is announced politely.
 */
import { useEffect, useId, useRef, useState, type FormEvent } from 'react';
import { QUIZ } from './data';
import styles from './styles.module.css';

export function Quiz() {
  const uid = useId();
  const [qi, setQi] = useState(0);
  const [choice, setChoice] = useState<number | null>(null);
  const [checked, setChecked] = useState(false);
  const [score, setScore] = useState(0);
  const [done, setDone] = useState(false);
  const [hint, setHint] = useState('');
  const firstRadio = useRef<HTMLInputElement>(null);
  const doneHead = useRef<HTMLHeadingElement>(null);
  const moved = useRef(false);
  const q = QUIZ[qi];

  useEffect(() => {
    if (!moved.current) return;
    moved.current = false;
    if (done) doneHead.current?.focus(); else firstRadio.current?.focus();
  }, [qi, done]);

  const submit = (e: FormEvent) => {
    e.preventDefault();
    if (!checked) {
      if (choice === null) { setHint('Choose an answer first.'); return; }
      setHint('');
      setChecked(true);
      if (choice === q.answer) setScore((s) => s + 1);
      return;
    }
    moved.current = true;
    if (qi + 1 >= QUIZ.length) { setDone(true); return; }
    setQi(qi + 1); setChoice(null); setChecked(false);
  };
  const restart = () => { moved.current = true; setQi(0); setChoice(null); setChecked(false); setScore(0); setDone(false); };

  if (done) {
    return (
      <div className={styles.poll}>
        <h4 ref={doneHead} tabIndex={-1} className={styles.question}>You got {score} of {QUIZ.length}</h4>
        <p className={styles.small}>{score === QUIZ.length ? 'Full marks — you have clearly been listening.' : 'Every answer was on this week’s show; the archive has the episodes.'} Nothing is scored or stored.</p>
        <button type="button" className={styles.ghost} onClick={restart}>Try again</button>
      </div>
    );
  }

  const right = checked && choice === q.answer;
  return (
    <form className={styles.poll} onSubmit={submit} noValidate>
      <fieldset className={styles.fieldset}>
        <legend className={styles.question}><span className={styles.qNo}>{qi + 1}/{QUIZ.length}</span> {q.q}</legend>
        <div className={styles.options}>
          {q.options.map((o, i) => (
            <label key={o} className={styles.option} data-answer={checked && i === q.answer ? 'right' : checked && i === choice ? 'wrong' : undefined}>
              <input ref={i === 0 ? firstRadio : undefined} type="radio" name={`${uid}-q${qi}`} checked={choice === i} aria-describedby={checked ? `${uid}-fb` : undefined}
                onChange={() => { if (checked) return; setChoice(i); setHint(''); }} />
              <span>{o}</span>
              {checked && i === q.answer ? <span className={styles.tag}>Answer</span> : null}
              {checked && i === choice && i !== q.answer ? <span className={styles.tag}>Your answer</span> : null}
            </label>
          ))}
        </div>
      </fieldset>
      <div id={`${uid}-fb`} className={styles.feedback} role="status" aria-live="polite">
        {checked ? (
          <p className={styles.feedbackText} data-right={right || undefined}>
            <span className={styles.feedbackMark} aria-hidden="true">{right ? '✓' : '✕'}</span>
            <strong>{right ? 'Correct.' : 'Not quite.'}</strong> {q.explain}
          </p>
        ) : hint ? <p className={styles.small}>{hint}</p> : null}
      </div>
      <div className={styles.actions}>
        <button type="submit" className={styles.primary}>{checked ? (qi + 1 >= QUIZ.length ? 'See my score' : 'Next question') : 'Check answer'}</button>
        <p className={styles.small}>Score so far: {score}</p>
      </div>
    </form>
  );
}

'use client';
/**
 * Ranking poll: the drag-reorder-list recipe is the ballot (pointer drag on the handle, or Space + arrows + Space;
 * Esc cancels). The recipe has no onChange, so "Send my order" reads the order it rendered — the titles are known
 * sample data — and adds it to the sample ballots. Results: average position per segment, yours alongside.
 */
import { useId, useRef, useState } from 'react';
import DragReorderList from '../../../effects/drag-reorder-list';
import { meta as reorderMeta } from '../../../effects/drag-reorder-list/meta';
import type { EffectMeta, ParamValues } from '../../../types';
import { RUNNING, RUNNING_BALLOTS } from './data';
import styles from './styles.module.css';

const defaults = (m: EffectMeta): ParamValues => Object.fromEntries(m.params.map((p) => [p.key, p.default]));
type Result = { id: string; title: string; avg: number; yours: number };

function readBallot(root: HTMLElement | null): string[] | null {
  const rows = root ? Array.from(root.querySelectorAll('ol > li')) : [];
  const ids = rows.map((li) => RUNNING.find((r) => (li.textContent ?? '').includes(r.title))?.id).filter((x): x is (typeof RUNNING)[number]['id'] => !!x);
  return ids.length === RUNNING.length && new Set(ids).size === RUNNING.length ? ids : null;
}

export function Ranking() {
  const uid = useId();
  const ballot = useRef<HTMLDivElement>(null);
  const resultsHead = useRef<HTMLHeadingElement>(null);
  const [results, setResults] = useState<Result[] | null>(null);
  const [error, setError] = useState('');

  const send = () => {
    const order = readBallot(ballot.current);
    if (!order) { setError('Your order could not be read. Nothing was sent; please try again.'); return; }
    setError('');
    const n = RUNNING_BALLOTS;
    const next = RUNNING.map((r) => {
      const yours = order.indexOf(r.id) + 1;
      return { id: r.id, title: r.title, yours, avg: (r.avg * n + yours) / (n + 1) };
    }).sort((a, b) => a.avg - b.avg);
    setResults(next);
    requestAnimationFrame(() => resultsHead.current?.focus());
  };

  return (
    <div className={styles.ranking}>
      <div ref={ballot} className={styles.ballot}>
        <DragReorderList params={{ ...defaults(reorderMeta), lift: 1.03, spring: 'settle', dragFrom: 'handle', times: true, density: 'compact' }} />
      </div>
      <div className={styles.actions}>
        <button type="button" className={styles.primary} onClick={send}>{results ? 'Send my new order' : 'Send my order'}</button>
        <p className={styles.small}>You can send again after changing it; only your latest order counts.</p>
      </div>
      {error ? <p className={styles.error} role="alert">{error}</p> : null}
      {results ? (
        <section className={styles.rankResults} aria-labelledby={`${uid}-rr`}>
          <h4 id={`${uid}-rr`} ref={resultsHead} tabIndex={-1} className={styles.question}>Listeners’ running order</h4>
          <p className={styles.small}>{(RUNNING_BALLOTS + 1).toLocaleString('en-GB')} ballots: {RUNNING_BALLOTS} sample ballots plus yours. Lower average = earlier in the show.</p>
          <ol className={styles.rankList}>
            {results.map((r, i) => (
              <li key={r.id}>
                <span className={styles.rankPos} aria-hidden="true">{i + 1}</span>
                <span className={styles.rankTitle}>{r.title}</span>
                <span className={styles.rankAvg}>avg {r.avg.toFixed(1)}</span>
                <span className={styles.rankYours} data-same={r.yours === i + 1 || undefined}>yours {r.yours}</span>
              </li>
            ))}
          </ol>
        </section>
      ) : null}
    </div>
  );
}

/* Quay FM listener polls — "studio cue cards": an FM dial with one red needle, cards with a red top rule and
   mono slugs like a presenter's running sheet, meter bars made of lit segments. One signal colour: on-air red. */
.root {
  --qf-red: #b3261e;   /* ≥ 5.19:1 on bg / surface / surface-2 */
  --qf-on-red: #ffffff;
  --mk-accent: var(--qf-red);
  min-height: 100dvh;
  padding: 0 16px 56px;
  background: var(--mk-bg);
  color: var(--mk-ink);
  font-family: var(--mk-font-text);
}
:global([data-theme='dark']) .root { --qf-red: #ff8f80; --qf-on-red: #11110f; }
.small { margin: 0; font-size: 0.8125rem; line-height: 1.5; color: var(--mk-ink-muted); }
.muted { color: var(--mk-ink-muted); }

.masthead { max-width: 1120px; margin: 0 auto; padding: 26px 0 8px; }
.mastRow { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 16px; }
.onAir { margin: 0; padding: 4px 10px; border-radius: 4px; background: var(--qf-red); color: var(--qf-on-red); font-family: var(--mk-font-mono); font-size: 0.75rem; font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; }
.sample { margin: 0; font-size: 0.8125rem; color: var(--mk-ink-muted); }
.sample > :first-child { margin-right: 8px; color: var(--mk-ink); }
.station { margin: 14px 0 0; font-family: var(--mk-font-display); font-size: clamp(3rem, 2rem + 6cqi, 6rem); font-weight: 800; line-height: 0.9; letter-spacing: -0.05em; }
.freq { font-family: var(--mk-font-mono); font-size: 0.42em; font-weight: 500; letter-spacing: -0.02em; vertical-align: 0.9em; color: var(--qf-red); }
.tagline { max-width: 52ch; margin: 12px 0 0; font-size: 1rem; line-height: 1.5; }
.dial { display: block; width: 100%; max-width: 720px; height: auto; margin-top: 18px; overflow: visible; }
.dialLine, .dialTick { stroke: var(--mk-ink); stroke-width: 1; }
.dialTick { stroke-width: 0.8; }
.dialNum { fill: var(--mk-ink-muted); font-family: var(--mk-font-mono); font-size: 9px; }
.needle { stroke: var(--qf-red); stroke-width: 2; }
.needleCap { fill: var(--qf-red); }

.grid { display: grid; gap: 22px; max-width: 1120px; margin: 22px auto 0; }
@container (min-width: 60rem) {
  .grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 26px; align-items: start; }
  .cue[data-wide] { grid-column: 1 / -1; }
}
.cue { position: relative; padding: 20px 16px 18px; border: 1px solid var(--mk-line); border-top: 4px solid var(--qf-red); border-radius: 4px 4px var(--mk-radius-m) var(--mk-radius-m); background: var(--mk-surface); }
@container (min-width: 36rem) { .cue { padding: 22px 22px 20px; } }
.slug { margin: 0; font-family: var(--mk-font-mono); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--qf-red); }
.cueTitle { margin: 6px 0 4px; font-family: var(--mk-font-display); font-size: 1.5rem; font-weight: 700; line-height: 1.1; letter-spacing: -0.02em; text-wrap: balance; }
/* The composed poll draws its own card; inside a cue card it only needs to sit flush. */
.composed { --mk-signal: var(--qf-red); --mk-on-signal: var(--qf-on-red); margin: 4px -8px -12px; }

/* ── Shared poll pieces ─────────────────────────────────────────────────── */
.poll { margin-top: 14px; }
.fieldset { min-width: 0; margin: 0; padding: 0; border: 0; }
.question { margin: 0 0 6px; padding: 0; font-family: var(--mk-font-display); font-size: 1.125rem; font-weight: 700; line-height: 1.25; letter-spacing: -0.01em; }
.qNo { margin-right: 6px; font-family: var(--mk-font-mono); font-size: 0.8125rem; font-weight: 500; color: var(--qf-red); }
.options { display: grid; gap: 8px; margin-top: 12px; }
.option {
  position: relative; display: flex; flex-wrap: wrap; align-items: center; gap: 6px 12px; min-height: 48px; padding: 10px 14px; box-sizing: border-box;
  border: 1px solid var(--mk-line-strong); border-radius: var(--mk-radius-m); font-size: 0.9375rem; cursor: pointer;
}
.option input { flex: none; width: 20px; height: 20px; margin: 0; accent-color: var(--qf-red); }
.option:has(input:checked) { border-width: 2px; padding: 9px 13px; font-weight: 600; }
.option[data-answer='right'] { border: 2px solid var(--mk-success); padding: 9px 13px; }
.option[data-answer='wrong'] { border: 2px dashed var(--mk-danger); padding: 9px 13px; }
.tag { padding: 2px 8px; border: 1px solid currentColor; border-radius: 999px; font-family: var(--mk-font-mono); font-size: 0.625rem; font-weight: 500; letter-spacing: 0.06em; text-transform: uppercase; }
.actions { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 16px; margin-top: 16px; }
.primary { min-height: 44px; padding: 0 20px; border: 0; border-radius: 999px; background: var(--mk-ink); color: var(--mk-bg); font: inherit; font-size: 0.9375rem; font-weight: 600; }
.primary:hover { background: var(--qf-red); color: var(--qf-on-red); }
.ghost { min-height: 44px; margin-top: 12px; padding: 0 18px; border: 1px solid var(--mk-line-strong); border-radius: 999px; background: transparent; color: inherit; font: inherit; font-size: 0.875rem; font-weight: 600; }
.ghost:hover { background: var(--mk-surface-2); }
.error { margin: 10px 0 0; font-size: 0.875rem; font-weight: 500; color: var(--mk-danger); }

/* Meter bars: lit segments on one shared scale */
.meters { display: grid; gap: 14px; margin: 14px 0 12px; padding: 0; list-style: none; }
.meterRow { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 6px 12px; align-items: baseline; }
.meterLabel { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 8px; font-size: 0.9375rem; font-weight: 500; }
.meterValue { font-family: var(--mk-font-mono); font-size: 0.875rem; font-variant-numeric: tabular-nums; text-align: right; }
.meter { grid-column: 1 / -1; display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); gap: 2px; height: 14px; }
.meter i { display: block; border-radius: 1px; background: var(--mk-surface-2); transition: background-color var(--mk-duration-base) var(--mk-ease-standard); }
.meter i[data-on] { background: var(--mk-ink); }
.meter i[data-peak] { background: var(--qf-red); }
.liveRow { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 4px 12px; margin-top: 12px; padding-top: 12px; border-top: 1px solid var(--mk-line); }
.liveRow .ghost { margin-top: 0; }
.liveText { display: flex; align-items: baseline; gap: 8px; margin: 0; font-size: 0.8125rem; line-height: 1.45; }
.liveDot { flex: none; width: 8px; height: 8px; border-radius: 50%; background: var(--mk-ink-muted); transform: translateY(-1px); }
.liveDot[data-on] { background: var(--qf-red); }

/* Quiz feedback */
.feedback { min-height: 1px; margin-top: 12px; }
.feedbackText { display: flex; gap: 10px; margin: 0; padding: 12px 14px; border-left: 4px solid var(--mk-danger); background: var(--mk-surface-2); font-size: 0.9375rem; line-height: 1.5; }
.feedbackText[data-right] { border-left-color: var(--mk-success); }
.feedbackMark { flex: none; font-weight: 700; }

/* Ranking */
.ranking { margin-top: 6px; }
.ballot { margin: 0 -8px; }
.rankResults { margin-top: 18px; padding-top: 16px; border-top: 1px solid var(--mk-line); }
.rankResults:focus-visible, .question:focus-visible { outline: 2px solid var(--mk-focus); outline-offset: 4px; }
.rankList { display: grid; gap: 0; margin: 12px 0 0; padding: 0; list-style: none; counter-reset: none; }
.rankList li { display: grid; grid-template-columns: 28px minmax(0, 1fr) auto auto; gap: 4px 14px; align-items: baseline; padding: 9px 0; border-bottom: 1px solid var(--mk-line); font-size: 0.9375rem; }
.rankPos { font-family: var(--mk-font-display); font-size: 1.25rem; font-weight: 800; color: var(--qf-red); }
.rankTitle { font-weight: 600; }
.rankAvg, .rankYours { font-family: var(--mk-font-mono); font-size: 0.8125rem; font-variant-numeric: tabular-nums; color: var(--mk-ink-muted); }
.rankYours[data-same] { color: var(--mk-ink); font-weight: 600; }
@container (max-width: 26rem) { .rankList li { grid-template-columns: 24px minmax(0, 1fr) auto; } .rankYours { grid-column: 2 / -1; } }

.footer { max-width: 1120px; margin: 40px auto 0; padding-top: 14px; border-top: 1px solid var(--mk-line); font-size: 0.8125rem; line-height: 1.55; color: var(--mk-ink-muted); }
.footer p { max-width: 75ch; margin: 0; }
